sys_variable_value.value:
(function() {
    // Create a template first
    var tpl = new GlideRecord('x_1919740_dayone_0_task_template');
    tpl.initialize();
    tpl.setValue('template_name', 'ATF Duplicate Test Template');
    tpl.setValue('applies_to_roles', '*');
    tpl.setValue('applies_to_locations', '*');
    tpl.setValue('department', 'hr');
    tpl.setValue('mandatory', true);
    tpl.setValue('est_days_to_complete', 3);
    tpl.setValue('active', true);
    tpl.setValue('description', 'Test template for duplicate prevention');
    var tplId = tpl.insert();

    var planGr = new GlideRecord('x_1919740_dayone_0_onboarding_plan');
    planGr.initialize();
    planGr.setValue('employee_name', 'ATF Duplicate Test');
    planGr.setValue('employee_id', 'ATF-013');
    planGr.setValue('role', 'Tester');
    planGr.setValue('location', 'Test Location');
    planGr.setValue('state', 'active');
    planGr.setValue('joining_date', '2025-06-01');
    var planId = planGr.insert();

    var gen = new DayOneTaskGenerator(planId);
    gen.generateTasks();

    var countGr = new GlideAggregate('x_1919740_dayone_0_onboarding_task');
    countGr.addQuery('plan', planId);
    countGr.addAggregate('COUNT');
    countGr.query();
    countGr.next();
    var firstCount = parseInt(countGr.getAggregate('COUNT'), 10);

    // Run again
    gen.generateTasks();

    countGr = new GlideAggregate('x_1919740_dayone_0_onboarding_task');
    countGr.addQuery('plan', planId);
    countGr.addAggregate('COUNT');
    countGr.query();
    countGr.next();
    var secondCount = parseInt(countGr.getAggregate('COUNT'), 10);

    if (firstCount !== secondCount) throw new Error('Duplicate tasks created: first=' + firstCount + ' second=' + secondCount);

    // Cleanup template
    tpl = new GlideRecord('x_1919740_dayone_0_task_template');
    if (tpl.get(tplId)) tpl.deleteRecord();

    gs.info('T-13 PASSED: No duplicates after running generator twice (' + firstCount + ' tasks)');
})();
